const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions (Dublin, Ireland)
    const aoi = ee.Geometry.Point([-6.2603, 53.3498]).buffer(25000).bounds(); // ~25 km buffer around Dublin center
    const totalAreaKm2 = (await ee.Number(aoi.area(1)).divide(1e6).getInfo());

    // Helper: Cloud mask for Landsat C2 L2
    function maskL2Clouds(img) {
      var qa = img.select('QA_PIXEL');
      var dilated = qa.bitwiseAnd(1 << 1).neq(0);
      var cirrus = qa.bitwiseAnd(1 << 2).neq(0);
      var cloud = qa.bitwiseAnd(1 << 3).neq(0);
      var shadow = qa.bitwiseAnd(1 << 4).neq(0);
      var snow = qa.bitwiseAnd(1 << 5).neq(0);
      var mask = dilated.or(cirrus).or(cloud).or(shadow).or(snow).not();
      return img.updateMask(mask);
    }

    // Helper: Scale and map to common bands
    function prepLandsatL2(img) {
      var sc = ee.String(img.get('SPACECRAFT_ID'));
      var scale = 0.0000275;
      var offset = -0.2;
      var isOLI = sc.compareTo('LANDSAT_8').eq(0).or(sc.compareTo('LANDSAT_9').eq(0));
      var green = ee.Image(ee.Algorithms.If(isOLI, img.select('SR_B3'), img.select('SR_B2'))).multiply(scale).add(offset);
      var red   = ee.Image(ee.Algorithms.If(isOLI, img.select('SR_B4'), img.select('SR_B3'))).multiply(scale).add(offset);
      var nir   = ee.Image(ee.Algorithms.If(isOLI, img.select('SR_B5'), img.select('SR_B4'))).multiply(scale).add(offset);
      var swir1 = ee.Image(ee.Algorithms.If(isOLI, img.select('SR_B6'), img.select('SR_B5'))).multiply(scale).add(offset);
      return ee.Image.cat([green, red, nir, swir1]).rename(['green','red','nir','swir1']).copyProperties(img, img.propertyNames());
    }

    function buildCollection(ids, start, end) {
      ids = ids || [];
      var col = ee.ImageCollection(ids[0]).filterBounds(aoi).filterDate(start, end).map(maskL2Clouds).map(prepLandsatL2);
      for (var i = 1; i < ids.length; i++) {
        var c = ee.ImageCollection(ids[i]).filterBounds(aoi).filterDate(start, end).map(maskL2Clouds).map(prepLandsatL2);
        col = col.merge(c);
      }
      return col;
    }

    async function getComposite(periodLabel, primaryIds, fallbackIds, start, end, widenStart, widenEnd) {
      let usedIds = primaryIds.slice();
      let usedRange = [start, end];
      let widened = false;
      let usedFallback = false;

      let col = buildCollection(primaryIds, start, end);
      let size = await col.size().getInfo();

      if (size === 0 && fallbackIds && fallbackIds.length > 0) {
        col = buildCollection(fallbackIds, start, end);
        size = await col.size().getInfo();
        usedIds = fallbackIds.slice();
        usedFallback = true;
      }
      if (size === 0) {
        col = buildCollection(primaryIds.concat(fallbackIds || []), widenStart, widenEnd);
        size = await col.size().getInfo();
        usedIds = primaryIds.concat(fallbackIds || []);
        usedRange = [widenStart, widenEnd];
        widened = true;
      }
      if (size === 0) {
        return { status: 'C1' };
      }
      const mosaic = col.median();
      return { status: 'OK', mosaic: mosaic, count: size, widened: widened, usedFallback: usedFallback, usedRange: usedRange, sensors: usedIds.join('+'), periodLabel: periodLabel };
    }

    function addIndices(img) {
      var green = img.select('green');
      var red = img.select('red');
      var nir = img.select('nir');
      var swir1 = img.select('swir1');
      var ndvi = nir.subtract(red).divide(nir.add(red)).rename('ndvi');
      var ndbi = swir1.subtract(nir).divide(swir1.add(nir)).rename('ndbi');
      var mndwi = green.subtract(swir1).divide(green.add(swir1)).rename('mndwi');
      var built = ndbi.gt(0).and(ndvi.lt(0.3)).and(mndwi.lt(0)).rename('built');
      return img.addBands([ndvi, ndbi, mndwi, built]);
    }

    async function statsForComposite(info) {
      if (info.status !== 'OK') return { status: info.status };
      var img = addIndices(info.mosaic);
      var ndvi = img.select('ndvi');
      var built = img.select('built');

      var totalCount = await ee.Image(1).rename('ones').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: 1000,
        maxPixels: 1e9
      }).getNumber('ones').getInfo();

      var validCount = await ndvi.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: 1000,
        maxPixels: 1e9
      }).getNumber('ndvi').getInfo();

      if (totalCount === null || validCount === null) return { status: 'C3' };
      if (validCount === 0) return { status: 'C2' };

      var builtAreaKm2 = await ee.Image.pixelArea().updateMask(built).reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: aoi,
        scale: 1000,
        maxPixels: 1e9
      }).getNumber('area').divide(1e6).getInfo();

      if (builtAreaKm2 === null || isNaN(builtAreaKm2)) return { status: 'C3' };

      var validPct = (validCount / totalCount) * 100.0;
      return {
        status: 'OK',
        meta: info,
        validCount: validCount,
        totalCount: totalCount,
        validPct: validPct,
        builtAreaKm2: builtAreaKm2
      };
    }

    // Periods
    const p1984 = await getComposite(
      '1984-11', ['LANDSAT/LT05/C02/T1_L2'], ['LANDSAT/LT04/C02/T1_L2'],
      '1984-11-01', '1984-12-01', '1984-10-15', '1984-12-15'
    );
    if (p1984.status === 'C1') {
      console.log('1984 Images: 0');
      console.log('C1');
      return;
    }
    const s1984 = await statsForComposite(p1984);
    if (s1984.status !== 'OK') {
      console.log(`1984 Status: ${s1984.status}`);
      console.log(s1984.status);
      return;
    }

    const p2022 = await getComposite(
      '2022-11', ['LANDSAT/LC09/C02/T1_L2', 'LANDSAT/LC08/C02/T1_L2'], [],
      '2022-11-01', '2022-12-01', '2022-10-15', '2022-12-15'
    );
    if (p2022.status === 'C1') {
      console.log('2022 Images: 0');
      console.log('C1');
      return;
    }
    const s2022 = await statsForComposite(p2022);
    if (s2022.status !== 'OK') {
      console.log(`2022 Status: ${s2022.status}`);
      console.log(s2022.status);
      return;
    }

    // Print concise evidence (<=20 lines)
    console.log(`AOI area (km²): ${totalAreaKm2.toFixed(1)}`);
    console.log(`1984 Images: ${p1984.count} [Sensors:${p1984.sensors}] [Range:${p1984.usedRange[0]}..${p1984.usedRange[1]}]`);
    console.log(`1984 Valid px: ${s1984.validCount}/${s1984.totalCount} (${s1984.validPct.toFixed(1)}%), Built-up (km²): ${s1984.builtAreaKm2.toFixed(2)}`);
    console.log(`2022 Images: ${p2022.count} [Sensors:${p2022.sensors}] [Range:${p2022.usedRange[0]}..${p2022.usedRange[1]}]`);
    console.log(`2022 Valid px: ${s2022.validCount}/${s2022.totalCount} (${s2022.validPct.toFixed(1)}%), Built-up (km²): ${s2022.builtAreaKm2.toFixed(2)}`);

    const diff = s2022.builtAreaKm2 - s1984.builtAreaKm2;
    console.log(`Δ Built-up (2022-1984) km²: ${diff.toFixed(2)}`);

    if (!isFinite(diff)) {
      console.log('C3');
      return;
    }
    if (diff > 0) {
      console.log('A');
    } else {
      console.log('B');
    }

  } catch (e) {
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
